/* ---- conectar à conta IPTV-S ---- */
.dlg-pair { text-align: center; }
.pair-code { font-size: 5rem; font-weight: 800; letter-spacing: .6rem; color: var(--accent2); margin: 1.6rem 0 1rem;
  font-family: Consolas, "Courier New", monospace; min-height: 6rem; display: flex; align-items: center; justify-content: center; }
.pair-code .spin { width: 3rem; height: 3rem; }
.pair-status { font-size: 1.1rem; }
.cloud-login { margin-top: .8rem; width: 100%; font-size: 1.05rem; }
/* ---- assinatura (bloqueio) ---- */
.dlg-gate { max-width: 60rem; }
.gate-info { margin-top: 1rem; padding: 1rem 1.2rem; border-radius: .8rem; background: rgba(124,92,255,.12); border: 1px solid rgba(124,92,255,.35); line-height: 1.5; }

/* plano mensal: pagar pela TV/PC */
.pay { margin-top: .6rem; text-align: center; }
.pay-head { color: var(--text) !important; font-size: 1.25rem !important; }
.pay-late { color: #ff6b6b; font-weight: 700; margin-left: .4rem; }
.pay-tabs { display: flex; justify-content: center; gap: .8rem; margin: .4rem 0 1rem; flex-wrap: wrap; }
.pay-tab { padding: .6rem 1.4rem; font-size: 1.05rem; }
.pay-tab.on { border-color: var(--accent2); color: var(--accent2); }
.pay-tab.on.focused { color: #fff; }
.pay-body { display: flex; flex-direction: column; align-items: center; }
.pay-qr { width: 19rem; height: 19rem; background-color: #fff; background-position: center; background-size: contain; background-repeat: no-repeat;
  border-radius: .8rem; border: .6rem solid #fff; margin-bottom: .8rem; }
.pay-how { margin-bottom: .6rem !important; }
.pay-code { font-family: monospace; font-size: .8rem !important; word-break: break-all; max-width: 46rem; opacity: .75; }
.pay-line { font-family: monospace; font-size: 1.2rem !important; color: var(--text) !important; letter-spacing: .05rem; }
.pay-msg { margin: 1rem 0 !important; }

